#define _POSIX_C_SOURCE 200809L
#include "common.h"
#include "frozen/core/octet.h"
#include <fcntl.h>
void lab_pre(struct Lab*l,World*w){(void)l;(void)w;}
void lab_post(struct Lab*l,World*w){(void)l;(void)w;}
/* Frozen core ecology: laboratory and terrarium-specific hooks are not enabled. */
static void die(const char*s){perror(s);exit(1);}
static void fail(const char*s){fprintf(stderr,"legacy: %s\n",s);exit(1);}
static void check(World*w){if(w->ncs<0||w->ncs>CMAX||w->nnb||w->cfg.w<1||w->cfg.w>GRID_W||w->cfg.h<1||w->cfg.h>GRID_H)fail("checkpoint bounds");for(int i=0;i<w->ncs;i++){Creature*c=w->cs[i];if(c->len<0||c->len>MAX_LEN||c->germ_len<0||c->germ_len>MAX_LEN||c->x<0||c->x>=w->cfg.w||c->y<0||c->y>=w->cfg.h||c->id<0||c->id>=w->nid)fail("creature bounds");}}
static void save(World*w,const char*d){check(w);char p[4096],q[4096];bridge_path(p,d,"state.ck");bridge_path(q,d,"state.ck.tmp");FILE*f=fopen(q,"wb");if(!f)die(q);World clean=*w;clean.rng=NULL;clean.lab=NULL;clean.before_vm=NULL;memset(clean.cs,0,sizeof clean.cs);memset(clean.nb,0,sizeof clean.nb);memset(clean.em,0,sizeof clean.em);uint64_t h=fnv1a(&clean,sizeof clean,FNV_INIT);h=fnv1a(w->rng,sizeof(Rng),h);for(int i=0;i<w->ncs;i++)h=fnv1a(w->cs[i],sizeof(Creature),h);uint64_t header[4]={0x3147454c444c5257ULL,sizeof(World),sizeof(Creature),h};if(fwrite(header,sizeof header,1,f)!=1||fwrite(&clean,sizeof clean,1,f)!=1||fwrite(w->rng,sizeof(Rng),1,f)!=1)die("checkpoint");for(int i=0;i<w->ncs;i++)if(fwrite(w->cs[i],sizeof(Creature),1,f)!=1)die("checkpoint creature");durable(f);if(rename(q,p))die("rename");int fd=open(d,O_RDONLY|O_DIRECTORY);if(fd<0||fsync(fd))die("directory sync");close(fd);}
static World*load(const char*d){char p[4096];bridge_path(p,d,"state.ck");FILE*f=records(p);uint64_t h[4];World*w=calloc(1,sizeof *w);if(fread(h,sizeof h,1,f)!=1||h[0]!=0x3147454c444c5257ULL||h[1]!=sizeof(World)||h[2]!=sizeof(Creature)||fread(w,sizeof *w,1,f)!=1||w->ncs<0||w->ncs>CMAX)fail("checkpoint header");uint64_t sum=fnv1a(w,sizeof *w,FNV_INIT);w->rng=calloc(1,sizeof(Rng));if(fread(w->rng,sizeof(Rng),1,f)!=1)fail("rng");sum=fnv1a(w->rng,sizeof(Rng),sum);for(int i=0;i<w->ncs;i++){w->cs[i]=calloc(1,sizeof(Creature));if(fread(w->cs[i],sizeof(Creature),1,f)!=1)fail("truncated creature");sum=fnv1a(w->cs[i],sizeof(Creature),sum);}if(sum!=h[3]||fgetc(f)!=EOF)fail("checksum/size");fclose(f);check(w);return w;}
static void append(World*w,const char*file){FILE*f=records(file);Creature c;while(read_record(f,&c,sizeof c)){if(w->ncs>=CMAX)fail("capacity exceeded");Creature*a=malloc(sizeof c);*a=c;a->id=w->nid++;a->parent=-1;a->x=rng_below(w->rng,w->cfg.w);a->y=rng_below(w->rng,w->cfg.h);w->occ[a->y][a->x]++;w->cs[w->ncs++]=a;}fclose(f);check(w);}
static void inspect(World*w){printf("tick=%ld population=%d births=%ld deaths=%ld emits=%ld stores=%ld eaten=%ld hash=%016llx\n",w->t,w->ncs,w->st.born,w->st.dead,w->st.emits,w->st.store_writes,w->st.energy_eaten,(unsigned long long)world_hash(w));}
static void watch(Creature*c,uint8_t op){if(op==OP_EMIT)adapter_emit(c->a);}
#define P(field,lo,hi) w->cfg.field=parameter(d,#field,w->cfg.field,lo,hi)
int main(int argc,char**argv){if(argc<3)fail("init DIR RAW SEED | step DIR N | inspect DIR | inject DIR RAW");const char*d=argv[2];World*w;
if(!strcmp(argv[1],"init")){if(argc<5)fail("args");refuse_existing(d);mkdir(d,0700);Rng*r=calloc(1,sizeof *r);rng_seed(r,strtoull(argv[4],NULL,10));WorldConfig cfg=cfg_default();cfg.w=GRID_W;cfg.h=GRID_H;cfg.max_pop=4096;w=world_new(NULL,0,r,&cfg,NULL);append(w,argv[3]);w->st.born=w->ncs;save(w,d);}
else{w=load(d);if(!strcmp(argv[1],"step")){if(argc<4)fail("args");P(food_regrow,0,10000);P(split_energy,1,1000000);P(mut_rate,0,1);P(dup_rate,0,1);P(max_pop,1,4096);P(ops_per_tick,1,4096);P(regs,0,1);P(germline,0,1);P(attack_steal,0,1000000);unsigned char b;if(stimulus(d,&b,1))w->stimulus=b;begin_emit(d);vm_set_watch(watch);for(unsigned n=strtoul(argv[3],NULL,10);n&&w->ncs;n--)world_step(w);vm_set_watch(NULL);end_emit();save(w,d);}else if(!strcmp(argv[1],"inject")){if(argc<4)fail("args");append(w,argv[3]);save(w,d);}else if(!strcmp(argv[1],"export")){if(argc<4)fail("args");FILE*f=fopen(argv[3],"wb");if(!f)fail("export open");for(int i=0;i<w->ncs;i++)if(fwrite(w->cs[i],sizeof(Creature),1,f)!=1)fail("export write");durable(f);}else if(strcmp(argv[1],"inspect"))fail("command");}inspect(w);Rng*r=w->rng;world_free(w);free(r);return 0;}
